/**
 * A eficiência do hexágono — porte de `componentes/viz/tesselacao.js`.
 *
 * A pergunta do módulo é geométrica e se responde OLHANDO: qual forma cobre o
 * plano sem deixar sobra? Triângulo, quadrado e hexágono ladrilham; o círculo
 * não — e os ~21,5% que ele desperdiça são o assunto.
 *
 * **A cena virou 2D.** No legado era um favo de prismas em 3D, e a inclinação da
 * câmera é justamente o que atrapalha aqui: em perspectiva, uma sobra pequena
 * some atrás da célula da frente. De cima, o vazio é o vermelho do fundo
 * aparecendo entre as peças — não há como confundir. É a mesma razão pela qual
 * um favo de mel se fotografa de frente.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, limitar, paleta, rodape, texto, titulo } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** O dourado da cera, quando a escolha é o favo; azul nas outras formas. */
const CERA = '#e3a431';

const tesselacao: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** Polígono regular de `lados`, com uma rotação inicial. */
  function celula(
    ctx: CanvasRenderingContext2D,
    cx: number,
    cy: number,
    raio: number,
    lados: number,
    giro: number,
  ): void {
    ctx.beginPath();
    for (let i = 0; i < lados; i++) {
      const a = giro + (i / lados) * Math.PI * 2;
      const x = cx + Math.cos(a) * raio;
      const y = cy + Math.sin(a) * raio;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const escolhido = typeof estado.escolhido === 'string' ? estado.escolhido : '';
    const ok = info.ok === true;

    if (escolhido === '') {
      titulo(ctx, L, A, 'Qual forma cobre o plano sem sobra?');
      texto(ctx, 'Escolha uma forma para ladrilhar.', L / 2, A * 0.52, limitar(A * 0.05, 11, 16), {
        cor: cor.fraco,
        peso: 700,
      });
      return;
    }

    titulo(ctx, L, A, ok ? 'Hexágonos: nenhuma sobra' : 'Veja o que sobra entre as peças');

    // A área ladrilhada. O fundo dela é o vermelho do desperdício: o que as
    // peças não cobrirem, aparece.
    const mx = L * 0.06;
    const my = A * 0.17;
    const mw = L * 0.88;
    const mh = A * 0.66;

    ctx.save();
    ctx.beginPath();
    ctx.rect(mx, my, mw, mh);
    ctx.clip();

    ctx.fillStyle = cor.erro;
    ctx.fillRect(mx, my, mw, mh);

    const ehHexagono = escolhido === 'hexagono';
    ctx.fillStyle = ehHexagono ? CERA : cor.azul;
    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 1.2;
    ctx.lineJoin = 'round';

    const R = limitar(Math.min(mw, mh) * 0.1, 14, 40);
    const cx0 = mx + mw / 2;
    const cy0 = my + mh / 2;
    const colunas = Math.ceil(mw / R) + 2;
    const linhas = Math.ceil(mh / R) + 2;

    if (escolhido === 'hexagono') {
      // Passo horizontal 1,5R e vertical √3R, com meia altura de defasagem: é o
      // encaixe que não deixa vão.
      const dx = R * 1.5;
      const dz = R * Math.sqrt(3);
      for (let c = -colunas; c <= colunas; c++) {
        for (let r = -linhas; r <= linhas; r++) {
          const x = cx0 + c * dx;
          const y = cy0 + r * dz + (Math.abs(c % 2) === 1 ? dz / 2 : 0);
          celula(ctx, x, y, R, 6, 0);
        }
      }
    } else if (escolhido === 'quadrado') {
      // O lado do quadrado inscrito é R√2; o passo é o próprio lado.
      const lado = R * Math.SQRT2;
      for (let c = -colunas; c <= colunas; c++) {
        for (let r = -linhas; r <= linhas; r++) {
          celula(ctx, cx0 + c * lado, cy0 + r * lado, R, 4, Math.PI / 4);
        }
      }
    } else if (escolhido === 'triangulo') {
      // Triângulos alternando ponta para cima e para baixo, meio lado defasados.
      const lado = R * Math.sqrt(3);
      const altura = lado * (Math.sqrt(3) / 2);
      for (let c = -colunas * 2; c <= colunas * 2; c++) {
        for (let r = -linhas; r <= linhas; r++) {
          const paraCima = (c + r) % 2 === 0;
          const x = cx0 + (c * lado) / 2;
          const y = cy0 + r * altura + (paraCima ? -R / 4 : R / 4);
          celula(ctx, x, y, R, 3, paraCima ? -Math.PI / 2 : Math.PI / 2);
        }
      }
    } else {
      // Círculos no empacotamento mais denso que existe — e ainda assim sobra.
      const dx = R * 2;
      const dz = R * Math.sqrt(3);
      for (let c = -colunas; c <= colunas; c++) {
        for (let r = -linhas; r <= linhas; r++) {
          const x = cx0 + c * dx + (Math.abs(r % 2) === 1 ? R : 0);
          const y = cy0 + r * dz;
          ctx.beginPath();
          ctx.arc(x, y, R, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();
        }
      }
    }

    ctx.restore();

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.strokeRect(mx, my, mw, mh);

    rodape(
      ctx,
      L,
      A,
      ok,
      'Cobre tudo, com o menor perímetro — o favo de mel ✔',
      escolhido === 'circulo'
        ? 'O vermelho é a sobra: ≈ 21,5% da área desperdiçada.'
        : 'Ladrilha sem sobra, mas gasta mais parede que o hexágono.',
      cor.fraco,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default tesselacao;
